package br.com.motiva.model;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

@Entity
@Table(name = "TRECHO_RODOVIA")
public class TrechoRodovia {

    // A tabela da Sprint 3 usa IDENTITY (GENERATED BY DEFAULT AS IDENTITY), nao sequence
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String codigo;
    private String rodovia;
    private Double kmInicio;
    private Double kmFim;
    private String municipio;
    private Double alturaGramaCm;
    private String densidadeVegetacao;
    private Integer diasSemCorte;
    private LocalDate ultimaVistoria;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getCodigo() { return codigo; }
    public void setCodigo(String codigo) { this.codigo = codigo; }
    public String getRodovia() { return rodovia; }
    public void setRodovia(String rodovia) { this.rodovia = rodovia; }
    public Double getKmInicio() { return kmInicio; }
    public void setKmInicio(Double kmInicio) { this.kmInicio = kmInicio; }
    public Double getKmFim() { return kmFim; }
    public void setKmFim(Double kmFim) { this.kmFim = kmFim; }
    public String getMunicipio() { return municipio; }
    public void setMunicipio(String municipio) { this.municipio = municipio; }
    public Double getAlturaGramaCm() { return alturaGramaCm; }
    public void setAlturaGramaCm(Double alturaGramaCm) { this.alturaGramaCm = alturaGramaCm; }
    public String getDensidadeVegetacao() { return densidadeVegetacao; }
    public void setDensidadeVegetacao(String densidadeVegetacao) { this.densidadeVegetacao = densidadeVegetacao; }
    public Integer getDiasSemCorte() { return diasSemCorte; }
    public void setDiasSemCorte(Integer diasSemCorte) { this.diasSemCorte = diasSemCorte; }
    public LocalDate getUltimaVistoria() { return ultimaVistoria; }
    public void setUltimaVistoria(LocalDate ultimaVistoria) { this.ultimaVistoria = ultimaVistoria; }
}
